INSERT INTO exercise_library (name, category, movement_pattern, exercise_type, primary_muscles, equipment_needed, logging_type, difficulty_level, suitable_for, coaching_cues, common_mistakes, default_sets, default_reps, default_rest_secs, source, is_active)
VALUES
  ('Slow Walking', 'cooldown', 'cardio', 'cardio', ARRAY['Full Body'], ARRAY['Bodyweight'], 'timed', 'beginner', ARRAY['Beginner','Intermediate','Advanced'], ARRAY['Walk at a relaxed pace; let heart rate come down gradually; shake out arms gently'], ARRAY['Stopping suddenly after intense exercise; sitting down immediately'], 1, '300s', 0, 'system', true),
  ('Standing Toe Touch', 'cooldown', 'static', 'static_stretch', ARRAY['Hamstrings'], ARRAY['Bodyweight'], 'timed', 'beginner', ARRAY['Beginner','Intermediate','Advanced'], ARRAY['Stand with feet together; bend forward from hips; reach for toes; keep knees slightly bent if needed'], ARRAY['Bouncing; rounding upper back excessively; locking knees'], 1, '30s', 0, 'system', true),
  ('Standing Quad Stretch', 'cooldown', 'static', 'static_stretch', ARRAY['Quads'], ARRAY['Bodyweight'], 'timed', 'beginner', ARRAY['Beginner','Intermediate','Advanced'], ARRAY['Stand on one leg; grab opposite foot behind you; pull heel to glute; keep knees together; hold a wall for balance'], ARRAY['Arching lower back; knee pointing outward; not holding long enough'], 1, '30s', 0, 'system', true),
  ('Overhead Stretch', 'cooldown', 'static', 'static_stretch', ARRAY['Shoulders'], ARRAY['Bodyweight'], 'timed', 'beginner', ARRAY['Beginner','Intermediate','Advanced'], ARRAY['Interlace fingers; push palms to ceiling; stretch tall; lean gently to each side'], ARRAY['Not fully extending arms; holding breath; arching lower back'], 1, '30s', 0, 'system', true),
  ('Side Bend Stretch', 'cooldown', 'static', 'static_stretch', ARRAY['Obliques'], ARRAY['Bodyweight'], 'timed', 'beginner', ARRAY['Beginner','Intermediate','Advanced'], ARRAY['Stand tall; raise one arm overhead; lean to the opposite side; hold 15s each side'], ARRAY['Leaning forward instead of sideways; not holding long enough'], 1, '30s', 0, 'system', true),
  ('Cross-body Shoulder Stretch', 'cooldown', 'static', 'static_stretch', ARRAY['Rear Deltoid'], ARRAY['Bodyweight'], 'timed', 'beginner', ARRAY['Beginner','Intermediate','Advanced'], ARRAY['Bring one arm across your chest; use opposite hand to press above the elbow; hold 15s each arm'], ARRAY['Pressing on the elbow joint; shrugging the shoulder; rotating the torso'], 1, '30s', 0, 'system', true),
  ('Chest Doorway Stretch', 'cooldown', 'static', 'static_stretch', ARRAY['Chest'], ARRAY['Bodyweight'], 'timed', 'beginner', ARRAY['Beginner','Intermediate','Advanced'], ARRAY['Place forearm on a doorframe or wall at 90 degrees; step forward until you feel the chest stretch; hold 15s each side'], ARRAY['Arm too high or too low; arching the lower back; not holding long enough'], 1, '30s', 0, 'system', true),
  ('Deep Breathing', 'cooldown', 'static', 'recovery', ARRAY['Core'], ARRAY['Bodyweight'], 'timed', 'beginner', ARRAY['Beginner','Intermediate','Advanced'], ARRAY['Stand or sit comfortably; place one hand on chest, one on belly; belly should rise on inhale; slow controlled exhales'], ARRAY['Shallow chest breathing; rushing the exhale; not relaxing shoulders'], 1, '60s', 0, 'system', true);
